    <script>
        $( document ).ready(function() {
            $("#submit-btn").click(function(e) {
                $('#loader').removeClass('d-none');
            });
        });
    </script>    
    <script>
        $(document).ready(function() {
            $('#passChange').on('shown.bs.modal',function(){
                $("#txtPass").focus();
            });
            $('#passChange').on('show.bs.modal',function(){
                $("#txtRePass").val('');
                $("#txtPass").val('');
            });

            $("#frmPassChange").on('submit', function(e) {
                e.preventDefault();
                $(".alertc").removeClass("alert").removeClass("alert-warning").removeClass("alert-success").removeClass("alert-danger");
                if ($("#txtPass").val() != $("#txtRePass").val()) {
                    $(".alertc").addClass("alert").addClass("alert-warning").text("Password mismatch!");
                    $("#txtPass").focus();
                } else {
                    $("#btnCP").prop("disabled",true);
                    var url1 = $(this).attr("action");
                    $.ajax({
                        url : url1, 
                        type : 'POST',
                        data : {"password" : $("#txtPass").val()}
                    })
                    .done(function(a){
                        $(".alertc").addClass("alert").addClass("alert-success").text("Password changed successfully!");
                        $("#btnCP").prop("disabled",false);

                    }).fail(function(){
                        $(".alertc").addClass("alert").addClass("alert-danger").text("Unable to change password!");
                        $("#btnCP").prop("disabled",false);

                    });
                }
            });

        });

    </script>
    <script>
        function updatewaitsubmit() {
